/* Run and clear the level's queued camera post-update callbacks. */
void Camera_RunQueuedCallbacks(void) {
    int i;
    for (i = 0; i < gCamPostUpdCountLvl; i++) {
        gCamPostUpdFuncsLvl[i]();
    }
    gCamPostUpdCountLvl = 0;
}
