// Samples the hero moby's three axes into blend.orbit.fwd and blend.orbit.up, derives the orbit yaw, pitch and distance to the hero, and copies rot to saved_rot.
/* Joined to the fragment that follows it (config/overlays/joined.tsv): the catalogue splits the delay slot of the final jr off. */
void Camera_CaptureHeroRelativeView(void) {
    float a[4];
    float b[4];
    float c[4];
    struct Hero *g = (struct Hero *)(hero_globals_base + 0xE1D);
    CamBlend *d = &player_camera.blend;

    vec_scale_to_length(a, *(char **)&g->moby + 0xC0, 1.0f);
    vec_scale_to_length(b, *(char **)&g->moby + 0xD0, 1.0f);
    vec_scale_to_length(c, *(char **)&g->moby + 0xE0, 1.0f);
    qcopy(&d->orbit.fwd, a);
    qcopy(&d->orbit.up, c);
    Camera_Pos2Polar3d(&d->orbit.yaw, &d->orbit.pos, &g->motion.pos, a, b, c);
    qcopy(&d->orbit.rot, &d->orbit.saved_rot);
}
