/* Camera mode update: in blend phase 1 the blend's next_kind picks what is captured from the
   previous camera (from), other phases restore the pending transform; then the phase becomes 3
   and kind takes next_kind: the lerp resets for kind 0, the orbit frame count advances otherwise.
   Level copy of func_001ECC48. */
void Camera_CaptureTransform(Camera *from) {
    CamBlend *r = &player_camera.blend;
    char local0[16];
    char local1[16];
    char local2[16];
    unsigned char sub;

    if (r->phase == 1) {
        sub = r->next_kind;
        if (sub == 0) {
            qcopy(&r->lerp.pos, &from->pos);
            extract_matrix_rotation_quaternion(&r->lerp.rot, from);
        } else if (sub == 2) {
            qcopy(&r->orbit.pos, &from->pos);
            extract_matrix_rotation_quaternion(&r->orbit.saved_rot, from);
            Camera_CaptureHeroRelativeView();
        } else {
            struct Hero *g = (struct Hero *)(hero_globals_base + 0xE1D);

            vec_scale_to_length(local0, *(char **)&g->moby + 0xC0, 1.0f);
            vec_scale_to_length(local1, *(char **)&g->moby + 0xD0, 1.0f);
            vec_scale_to_length(local2, *(char **)&g->moby + 0xE0, 1.0f);
            Camera_Pos2Polar3d(&r->orbit.yaw, &from->pos,
                          &(*(Camera **)((char *)r - 0xF0))->pos, /* player_camera.current */
                          local0, local1, local2);
            extract_matrix_rotation_quaternion(&r->orbit.rot, from);
            qcopy(&r->orbit.saved_rot, &r->orbit.rot);
        }
    } else {
        sub = r->next_kind;
        if (sub == 2) {
            save_camera_vectors();
            Camera_CaptureHeroRelativeView();
        } else if (sub == 1) {
            save_camera_vectors();
            qcopy(&r->orbit.rot, &r->orbit.saved_rot);
        } else if (sub == 0) {
            restore_camera_vectors();
        }
    }
    camera_blend_phase_h = 3; /* blend.phase */
    r->kind = r->next_kind;
    if (r->kind == 0) {
        CamBlendLerp *a = &r->lerp;

        a->pos_rate = a->pos_rate_cfg;
        a->pos_t = 0;
        qcopy(&r->lerp.from_pos, &r->lerp.pos);
        a->rot_t = 0;
        a->rot_rate = a->rot_rate_cfg;
        qcopy(&r->lerp.from_rot, &r->lerp.rot);
    } else {
        CamBlendOrbit *o = &r->orbit;
        int n = ++o->frames;

        o->frames_left = scale_ticks(n);
        o->inv_frames = 1.0f / IntToFloat(o->frames_left);
    }
}
