/* Returns the index of the entry with the given key, or of the -1 terminator. */
int find_camera_table_index_by_id(int key) {
    int i = 0;
    while (gCameraTypesLvl[i].id != -1 && gCameraTypesLvl[i].id != key) {
        i++;
    }
    return i;
}
